class Solution {
public:
 int maxTaskAssign(vector<int>& tasks,vector<int>& workers,int pills,int strength){
  sort(tasks.begin(),tasks.end()); sort(workers.begin(),workers.end());
  int n=tasks.size(),m=workers.size();
  auto ok=[&](int k){
   deque<int> dq; int i=0,p=pills;
   for(int j=m-k;j<m;++j){
    while(i<k && tasks[i]<=workers[j]+strength) dq.push_back(tasks[i++]);
    if(dq.empty()) return false;
    if(dq.front()<=workers[j]) dq.pop_front();
    else {if(!p) return false; --p; dq.pop_back();}
   }
   return true;
  };
  int lo=0,hi=min(n,m);
  while(lo<hi){int mid=(lo+hi+1)/2;if(ok(mid))lo=mid;else hi=mid-1;}
  return lo;
 }
};
